import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';
import { generateBranchName } from '../ai/branchName.js';

export function registerBranch(program: Command) {
  const branch = program.command('branch').description('Branch utilities');

  branch
    .command('create <description>')
    .option('--ai', 'Generate branch name from description')
    .option('-n, --name <name>', 'Explicit branch name')
    .action(async (description, opts) => {
      const spinner = ora('Creating branch...').start();
      const name = opts.ai ? await generateBranchName(description) : (opts.name || description);
      await git().checkoutLocalBranch(name);
      spinner.succeed(`Created branch ${name}`);
    });
}
